USE [JamunaBankProcurement];
GO
SET ANSI_NULLS ON;
GO
SET QUOTED_IDENTIFIER ON;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetCategory_GetAll @ActiveOnly BIT=1 AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.ASSET_CATEGORY WHERE @ActiveOnly=0 OR IS_ACTIVE=1 ORDER BY CATEGORY_NAME; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Asset_GetAll @CategoryId BIGINT=NULL,@ActiveOnly BIT=1 AS BEGIN SET NOCOUNT ON; SELECT a.ASSET_ID,a.ASSET_CATEGORY_ID,c.CATEGORY_NAME,a.ASSET_CODE,a.ASSET_NAME,a.DESCRIPTION,a.UNIT_OF_MEASUREMENT,a.DEFAULT_WARRANTY,a.USEFUL_LIFE,a.CAPITALIZATION_THRESHOLD,a.CRITICALITY,a.IS_INVENTORY_ITEM,a.IS_DEPRECIABLE,a.IS_ACTIVE FROM dbo.ASSET_MASTER a INNER JOIN dbo.ASSET_CATEGORY c ON c.ASSET_CATEGORY_ID=a.ASSET_CATEGORY_ID WHERE (@CategoryId IS NULL OR a.ASSET_CATEGORY_ID=@CategoryId) AND (@ActiveOnly=0 OR a.IS_ACTIVE=1) ORDER BY a.ASSET_NAME; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Asset_GetById @AssetId BIGINT AS BEGIN SET NOCOUNT ON; SELECT a.ASSET_ID,a.ASSET_CATEGORY_ID,c.CATEGORY_NAME,a.ASSET_CODE,a.ASSET_NAME,a.DESCRIPTION,a.UNIT_OF_MEASUREMENT,a.DEFAULT_WARRANTY,a.USEFUL_LIFE,a.CAPITALIZATION_THRESHOLD,a.CRITICALITY,a.IS_INVENTORY_ITEM,a.IS_DEPRECIABLE,a.IS_ACTIVE FROM dbo.ASSET_MASTER a INNER JOIN dbo.ASSET_CATEGORY c ON c.ASSET_CATEGORY_ID=a.ASSET_CATEGORY_ID WHERE a.ASSET_ID=@AssetId; EXEC dbo.usp_AssetSpec_GetByAsset @AssetId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Asset_Create @CategoryId BIGINT,@AssetCode VARCHAR(30),@AssetName NVARCHAR(200),@Description NVARCHAR(1000)=NULL,@Uom NVARCHAR(50),@DefaultWarranty INT=NULL,@UsefulLife INT=NULL,@CapitalizationThreshold DECIMAL(18,2)=NULL,@Criticality VARCHAR(20)='MEDIUM',@IsInventoryItem BIT=1,@IsDepreciable BIT=1,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY INSERT dbo.ASSET_MASTER(ASSET_CATEGORY_ID,ASSET_CODE,ASSET_NAME,DESCRIPTION,UNIT_OF_MEASUREMENT,DEFAULT_WARRANTY,USEFUL_LIFE,CAPITALIZATION_THRESHOLD,CRITICALITY,IS_INVENTORY_ITEM,IS_DEPRECIABLE,CREATED_BY) VALUES(@CategoryId,@AssetCode,@AssetName,@Description,@Uom,@DefaultWarranty,@UsefulLife,@CapitalizationThreshold,@Criticality,@IsInventoryItem,@IsDepreciable,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_Asset_Update @AssetId BIGINT,@CategoryId BIGINT,@AssetCode VARCHAR(30),@AssetName NVARCHAR(200),@Description NVARCHAR(1000)=NULL,@Uom NVARCHAR(50),@DefaultWarranty INT=NULL,@UsefulLife INT=NULL,@CapitalizationThreshold DECIMAL(18,2)=NULL,@Criticality VARCHAR(20),@IsInventoryItem BIT,@IsDepreciable BIT,@IsActive BIT,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; BEGIN TRY UPDATE dbo.ASSET_MASTER SET ASSET_CATEGORY_ID=@CategoryId,ASSET_CODE=@AssetCode,ASSET_NAME=@AssetName,DESCRIPTION=@Description,UNIT_OF_MEASUREMENT=@Uom,DEFAULT_WARRANTY=@DefaultWarranty,USEFUL_LIFE=@UsefulLife,CAPITALIZATION_THRESHOLD=@CapitalizationThreshold,CRITICALITY=@Criticality,IS_INVENTORY_ITEM=@IsInventoryItem,IS_DEPRECIABLE=@IsDepreciable,IS_ACTIVE=@IsActive,MODIFIED_BY=@Actor,MODIFIED_DATE=SYSUTCDATETIME() WHERE ASSET_ID=@AssetId; SELECT CASE WHEN @@ROWCOUNT=1 THEN '000' ELSE '002' END RESULT_CODE,CASE WHEN @@ROWCOUNT=1 THEN N'Success' ELSE N'Not found' END RESULT_MESSAGE,@AssetId ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,@AssetId ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetSpec_GetByAsset @AssetId BIGINT AS BEGIN SET NOCOUNT ON; SELECT d.*,o.ASSET_SPEC_OPTION_ID,o.OPTION_VALUE,o.DISPLAY_ORDER OPTION_DISPLAY_ORDER,o.IS_ACTIVE OPTION_IS_ACTIVE FROM dbo.ASSET_SPEC_DEFINITION d LEFT JOIN dbo.ASSET_SPEC_OPTION o ON o.ASSET_SPEC_ID=d.ASSET_SPEC_ID WHERE d.ASSET_ID=@AssetId ORDER BY d.DISPLAY_ORDER,o.DISPLAY_ORDER; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_AssetOfficerMap_Save @AssetId BIGINT,@EmployeeId VARCHAR(30),@IsPrimary BIT,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY INSERT dbo.PROC_OFFICER_ASSET_MAP(ASSET_ID,EMPLOYEE_ID,IS_PRIMARY,EFFECTIVE_FROM,EFFECTIVE_TO,CREATED_BY) VALUES(@AssetId,@EmployeeId,@IsPrimary,@EffectiveFrom,@EffectiveTo,@Actor); SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,CONVERT(BIGINT,SCOPE_IDENTITY()) ENTITY_ID,NULL REFERENCE_NO; END TRY BEGIN CATCH SELECT CASE WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,NULL REFERENCE_NO; END CATCH END;
GO
